105	    {
106	        int version = _programs.Version;
107	        for (int i = 0; i < ScriptCacheCapacity; i++)
108	        {
109	            if (_cachedGraphIds[i] != graphId || _cachedVersions[i] != version)
110	            {
111	                continue;
112	            }
113	
114	            GraphInstruction[]? cached = _cachedPrograms[i];
115	            if (cached != null)
116	            {
117	                return cached;
118	            }
119	        }
120	
121	        GraphInstruction[] program = _programs.RequireProgramArray(graphId, GraphKind.Script, hostLabel);
122	        int slot = _nextCacheSlot;
123	        _nextCacheSlot = (slot + 1) % ScriptCacheCapacity;
124	        _cachedGraphIds[slot] = graphId;
125	        _cachedVersions[slot] = version;
126	        _cachedPrograms[slot] = program;
127	        return program;
