48	    private GraphSliceResult ExecuteHalt(int graphId, string hostLabel)
49	    {
50	        GraphInstruction[] program = ResolveScriptProgram(graphId, hostLabel);
51	        if (TryExecuteImmediateHalt(program, out int immediateReturn))
52	        {
53	            return new GraphSliceResult(GraphExecutionStatus.Halted, immediateReturn, steps: 2);
54	        }
55	
56	        Array.Clear(_ints, 0, _ints.Length);
57	        Array.Clear(_bools, 0, _bools.Length);
58	        Array.Clear(_callStack, 0, _callStack.Length);
59	        var cursor = new GraphExecutionCursor();
60	        GraphSliceResult result = GraphExecutor.ExecuteResolvedRegisteredScriptSlice(
61	            _programs,
62	            program,
63	            _ints,
64	            _bools,
65	            _callStack,
66	            ref cursor,
67	            budgetSteps: 64,
68	            _world,
69	            api: _api);
70	        if (!result.Halted)
71	        {
72	            throw new InvalidOperationException("HFSM-bound Script must halt within budget.");
73	        }
74	
