350	
351	            // Measure registry/Api hot path only (VM Execute harness can allocate cursor/state noise).
352	            int sink = 0;
353	            float sinkF = 0f;
354	            for (int i = 0; i < 32; i++)
355	            {
356	                int row = api.ResolveTableRow(tableId, 2);
357	                sink ^= api.TableReadInt(tokenField, row);
358	                sinkF += api.TableReadFloat(scaleField, row);
