361	            GC.Collect();
362	            GC.WaitForPendingFinalizers();
363	            GC.Collect();
364	
365	            long before = GC.GetAllocatedBytesForCurrentThread();
366	            for (int i = 0; i < 256; i++)
367	            {
368	                int row = api.ResolveTableRow(tableId, 2);
369	                sink ^= api.TableReadInt(tokenField, row);
370	                sinkF += api.TableReadFloat(scaleField, row);
371	            }
372	
373	            long allocated = GC.GetAllocatedBytesForCurrentThread() - before;
374	            Assert.That(sink, Is.Not.EqualTo(int.MinValue));
375	            Assert.That(sinkF, Is.Not.EqualTo(float.MinValue));
376	            Assert.That(allocated, Is.EqualTo(0));
