    var snapshot = new List<ResolvedLocalSeatPossession>(seats.Count);
    IReadOnlyList<string> ids = seats.SeatIds;
    for (int i = 0; i < ids.Count; i++)
    {
        Client.ClientLocalSeat seat = seats.Require(ids[i]);
        if (!seat.HasPossession)
