        BindScopeRef(engine, host, scopeKeyId, host);
        for (int j = 0; j < cfg.Members.Length; j++)
        {
            BindScopeRef(engine, ResolveEntity(cfg.Members[j]), scopeKeyId, host);
        }
    }
}

