70	            }
71	
72	            if (!buffer.HasAttribute(id))
73	            {
74	                throw new InvalidOperationException(
75	                    $"Panel binding '{binding.VariableId}' attribute '{attributeId}' is not defined on owner #{owner.Id}.");
76	            }
77	
78	            float value = buffer.GetCurrent(id);
