            { "control": "lbl.squad", "variable": "squadAttack" },
            { "control": "lbl.rank", "variable": "rank.badge" }
          ],
          "events": [
            { "eventId": "ui.entity.inspect", "gesture": "click", "control": "row.entity",
              "payload": { "entityId": "Int", "verbose": "Bool" } }
          ],
          "intents": [
