79	    {
80	        returnInt = 0;
81	        if (program.Length != 2)
82	        {
83	            return false;
84	        }
85	
86	        ref readonly GraphInstruction first = ref program[0];
87	        ref readonly GraphInstruction second = ref program[1];
88	        if (first.Op != (ushort)GraphNodeOp.ConstInt ||
89	            second.Op != (ushort)GraphNodeOp.HaltReturnInt)
90	        {
91	            return false;
92	        }
93	
94	        if ((uint)first.Dst >= GraphVmLimits.MaxIntRegisters ||
95	            (uint)second.A >= GraphVmLimits.MaxIntRegisters)
96	        {
97	            return false;
98	        }
99	
100	        returnInt = second.A == first.Dst ? first.Imm : 0;
101	        return true;
