            string trimmed = op.Trim();
            if (Enum.TryParse(trimmed, ignoreCase: false, out GraphNodeOp v) &&
                v != GraphNodeOp.None &&
                Enum.IsDefined(typeof(GraphNodeOp), v) &&
                string.Equals(v.ToString(), trimmed, StringComparison.Ordinal))
            {
                parsed = v;
                return true;
            }

            return false;
        }
    }
