340	        [Test]
341	        public void HotPath_ResolveAndRead_ZeroAllocAfterWarmup()
342	        {
343	            var tables = CreateRankTable(tokenVeteran: 9);
344	            int tableId = tables.GetTableId("mod.example.rank_display");
345	            int tokenField = tables.GetFieldId("mod.example.rank_display", "displayToken");
346	            int scaleField = tables.GetFieldId("mod.example.rank_display", "powerScale");
347	
348	            using World world = World.Create();
349	            var api = new GasGraphRuntimeApi(world, lookupTables: tables);
350	
351	            // Measure registry/Api hot path only (VM Execute harness can allocate cursor/state noise).
352	            int sink = 0;
353	            float sinkF = 0f;
354	            for (int i = 0; i < 32; i++)
355	            {
356	                int row = api.ResolveTableRow(tableId, 2);
357	                sink ^= api.TableReadInt(tokenField, row);
358	                sinkF += api.TableReadFloat(scaleField, row);
359	            }
360	
361	            GC.Collect();
362	            GC.WaitForPendingFinalizers();
363	            GC.Collect();
364	
365	            long before = GC.GetAllocatedBytesForCurrentThread();
366	            for (int i = 0; i < 256; i++)
367	            {
368	                int row = api.ResolveTableRow(tableId, 2);
369	                sink ^= api.TableReadInt(tokenField, row);
370	                sinkF += api.TableReadFloat(scaleField, row);
371	            }
372	
373	            long allocated = GC.GetAllocatedBytesForCurrentThread() - before;
374	            Assert.That(sink, Is.Not.EqualTo(int.MinValue));
375	            Assert.That(sinkF, Is.Not.EqualTo(float.MinValue));
376	            Assert.That(allocated, Is.EqualTo(0));
377	        }
