506	        private static (int[] Ints, float[] Floats) Execute(
507	            World world,
508	            IGraphRuntimeApi api,
509	            Entity caster,
510	            GraphInstruction[] program)
511	        {
512	            var f = new float[GraphVmLimits.MaxFloatRegisters];
513	            var i = new int[GraphVmLimits.MaxIntRegisters];
514	            var e = new Entity[GraphVmLimits.MaxEntityRegisters];
515	            var b = new byte[GraphVmLimits.MaxBoolRegisters];
516	            var targets = new Entity[GraphVmLimits.MaxTargets];
517	            e[0] = caster;
518	            e[1] = caster;
519	            var state = new GraphExecutionState
520	            {
521	                World = world,
522	                Api = api,
523	                Caster = caster,
524	                ExplicitTarget = caster,
525	                F = f,
526	                I = i,
527	                E = e,
528	                B = b,
529	                Targets = targets,
530	                TargetList = new GraphTargetList(targets),
531	                CallStack = new int[GraphVmLimits.MaxCallStackDepth],
532	                CallStackCount = 0,
533	            };
534	            GasGraphOpHandlerTable.Execute(ref state, program, GasGraphOpHandlerTable.Instance);
535	            return (state.I.ToArray(), state.F.ToArray());
536	        }
