        return explicitResolution;
    }

    if (engine.GetService(CoreServiceKeys.ViewController) is Presentation.Camera.IViewController view &&
        view.Resolution.X > 0f &&
        view.Resolution.Y > 0f)
    {
        return view.Resolution;
    }

