34	        public PanelProjectionValue Resolve(Entity owner, in PanelVariableBinding binding)
35	        {
36	            if (owner == Entity.Null || !_world.IsAlive(owner))
37	            {
38	                throw new InvalidOperationException(
39	                    $"Panel binding '{binding.VariableId}' requires a live owner entity.");
40	            }
41	
42	            return binding.SourceKind switch
43	            {
44	                PanelBindingSourceKind.SingleAttribute or PanelBindingSourceKind.DerivedAttribute
45	                    => ResolveAttribute(owner, in binding),
46	                PanelBindingSourceKind.AggregateProjection or PanelBindingSourceKind.GraphOutput
47	                    => ResolveGraphOutput(owner, in binding),
48	                _ => throw new InvalidOperationException(
49	                    $"Panel binding '{binding.VariableId}' has unsupported sourceKind '{binding.SourceKind}'."),
50	            };
51	        }
