53	        private PanelProjectionValue ResolveAttribute(Entity owner, in PanelVariableBinding binding)
54	        {
55	            string attributeId = binding.AttributeId
56	                ?? throw new InvalidOperationException(
57	                    $"Panel binding '{binding.VariableId}' is missing attributeId.");
58	
59	            int id = _resolveAttributeId(attributeId);
60	            if (id == AttributeRegistry.InvalidId || id < 0)
61	            {
62	                throw new InvalidOperationException(
63	                    $"Panel binding '{binding.VariableId}' references unknown attribute '{attributeId}'.");
64	            }
65	
66	            if (!_world.TryGet(owner, out AttributeBuffer buffer))
67	            {
68	                throw new InvalidOperationException(
69	                    $"Panel binding '{binding.VariableId}' requires AttributeBuffer on owner #{owner.Id} for attribute '{attributeId}'.");
70	            }
71	
72	            if (!buffer.HasAttribute(id))
73	            {
74	                throw new InvalidOperationException(
75	                    $"Panel binding '{binding.VariableId}' attribute '{attributeId}' is not defined on owner #{owner.Id}.");
76	            }
77	
78	            float value = buffer.GetCurrent(id);
79	            uint revision = (uint)BitConverter.SingleToInt32Bits(value);
80	            return new PanelProjectionValue(binding.VariableId, binding.SourceKind, value, revision);
81	        }
