    /// Evaluation is event-driven: whoever writes signals calls <see cref="Evaluate"/>;
    /// there is no per-frame tick.
    /// </summary>
    public sealed class PanelOrchestrationRuntime
    {
        private static readonly PanelActivationWriteToken WriteToken = new(0);

        private readonly UiPanelActivationStore _store;
        private readonly GraphProgramRegistry _programs;
        private readonly List<(string PanelType, int GraphId)> _resolved;

        // Caller-owned scratch per the executor contract (heap allocation forbidden on this path).
        private readonly int[] _ints = new int[GraphVmLimits.MaxIntRegisters];
        private readonly byte[] _bools = new byte[GraphVmLimits.MaxBoolRegisters];
        private readonly int[] _callStack = new int[GraphVmLimits.MaxCallStackDepth];

        public PanelOrchestrationRuntime(
            IEnumerable<PanelOrchestrationEntry> entries,
            GraphProgramRegistry programs,
            UiPanelActivationStore store)
        {
            ArgumentNullException.ThrowIfNull(entries);
            _programs = programs ?? throw new ArgumentNullException(nameof(programs));
            _store = store ?? throw ArgumentNullException(nameof(store));

            _resolved = new List<(string, int)>();
            var seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (PanelOrchestrationEntry entry in entries)
            {
                if (entry == null)
                {
                    throw new ArgumentException("Orchestration entries must not be null.", nameof(entries));
                }

                if (!seen.Add(entry.PanelType))
                {
                    throw new ArgumentException($"Duplicate orchestration entry for panel '{entry.PanelType}'.", nameof(entries));
                }

                int graphId = NodeLibraries.GASGraph.Host.GraphIdRegistry.GetId(entry.GraphId);
                if (graphId <= 0)
                {
                    throw new InvalidOperationException(
                        $"Panel orchestration for '{entry.PanelType}' references unregistered graph '{entry.GraphId}'.");
                }

                // Fail now, not at first evaluation: the graph must already be a registered Script.
                _ = _programs.RequireProgram(graphId, GraphKind.Script, $"panel orchestration '{entry.PanelType}'");
                _resolved.Add((entry.PanelType, graphId));
            }
        }

        public UiPanelActivationStore Store => _store;

        /// <summary>
        /// Event-driven evaluation: run every mapped Script graph to halt against the
        /// context entity and apply the activation set. Callers invoke this from signal
        /// write sites (panel events, context changes) — never from a frame tick.
        /// </summary>
        public PanelActivationDiff Evaluate(World world, IGraphRuntimeApi api, Entity contextEntity)
        {
            ArgumentNullException.ThrowIfNull(world);
            ArgumentNullException.ThrowIfNull(api);
            if (contextEntity == Entity.Null || !world.IsAlive(contextEntity))
            {
                throw new InvalidOperationException("Panel orchestration requires a live context entity.");
            }

            var desired = new Dictionary<string, bool>(_resolved.Count, StringComparer.Ordinal);
            foreach ((string panelType, int graphId) in _resolved)
            {
                GraphInstruction[] program = _programs.RequireProgramArray(graphId, GraphKind.Script, $"panel orchestration '{panelType}'");
                desired[panelType] = ExecuteToHalt(world, api, contextEntity, program);
            }

            return _store.Apply(WriteToken, desired);
        }

        private bool ExecuteToHalt(World world, IGraphRuntimeApi api, Entity contextEntity, GraphInstruction[] program)
        {
            Array.Clear(_ints, 0, _ints.Length);
            Array.Clear(_bools, 0, _bools.Length);
            Array.Clear(_callStack, 0, _callStack.Length);
            var cursor = new GraphExecutionCursor();
            GraphSliceResult result = GraphExecutor.ExecuteResolvedRegisteredScriptSlice(
                _programs,
                program,
                _ints,
                _bools,
                _callStack,
                ref cursor,
                budgetSteps: 64,
                world,
                caster: contextEntity,
                explicitTarget: contextEntity,
                api: api);
            if (!result.Halted)
            {
                throw new InvalidOperationException(
                    "Panel orchestration Script must halt within budget; Yield is not allowed in visibility graphs.");
            }

            return result.ReturnInt != 0;
        }
    }
}
